create type "public"."article_ai_status" as enum (
  'pending',
  'done',
  'failed'
);


create table "public"."article_ai_results" (
  "id" bigint generated by default as identity not null,
  "article_id" bigint not null,
  "summary" text,
  "abuse_score" numeric,
  "abuse_label" text,
  "keywords" text[],
  "status" public.article_ai_status not null default 'pending',
  "last_error" text,
  "created_at" timestamp not null default now(),
  "updated_at" timestamp not null default now()
);


alter table "public"."article_ai_results" enable row level security;


CREATE UNIQUE INDEX article_ai_results_pkey
ON public.article_ai_results USING btree (id);

alter table "public"."article_ai_results"
add constraint "article_ai_results_pkey"
PRIMARY KEY using index "article_ai_results_pkey";


alter table "public"."article_ai_results"
add constraint "article_ai_results_article_id_fkey"
FOREIGN KEY (article_id)
REFERENCES public.articles(id)
ON DELETE CASCADE
not valid;

alter table "public"."article_ai_results"
validate constraint "article_ai_results_article_id_fkey";


CREATE TRIGGER set_updated_at
BEFORE UPDATE ON public.article_ai_results
FOR EACH ROW
EXECUTE FUNCTION public.update_updated_at();


grant select on table "public"."article_ai_results" to "authenticated";

grant select, insert, update, delete on table "public"."article_ai_results" to "service_role";
grant references on table "public"."article_ai_results" to "service_role";
grant trigger on table "public"."article_ai_results" to "service_role";
grant truncate on table "public"."article_ai_results" to "service_role";


create policy "No access for users"
on "public"."article_ai_results"
as permissive
for select
to authenticated
using (false);